export function localDate(value: IsoTimestamp, timeZone: string): string {
  const parts = new Intl.DateTimeFormat(\"en-US\", {
    timeZone, year: \"numeric\", month: \"2-digit\", day: \"2-digit\",
  }).formatToParts(parseIso(value));
  const part = (name: string) => parts.find((p) => p.type === name)"'!.value;
  return `${part("year")}-${part("month")}-${part("day")}`;
}

export function localHour(reference: Date, timeZone: string): number {
  return Number(new Intl.DateTimeFormat("en-US", {
    timeZone, hour: "2-digit", hourCycle: "h23",
  }).format(reference));
}

/** Resolve a wall-clock hour; folds use the earlier instant, gaps move forward. */
function wallTime(day: string, hour: number, timeZone: string): IsoTimestamp {
  const target = Date.parse(`${day}T00:00:00.000Z`) + hour * HOUR_MS;
  const offsets = new Set<number>();
  for (const delta of [-36, -12, 0, 12, 36]) {
    const instant = new Date(target + delta * HOUR_MS);
    const date = localDate(toIsoTimestamp(instant), timeZone);
    const wall = Date.parse(`${date}T00:00:00.000Z`) + localHour(instant, timeZone) * HOUR_MS
      + instant.getUTCMinutes() * MINUTE_MS + instant.getUTCSeconds() * 1000;
    offsets.add(wall - instant.getTime());
  }
  const candidates = [...offsets].map((offset) => target - offset).sort((a, b) => a - b);
  const exact = candidates.filter((value) => {
    const instant = new Date(value);
    return localDate(toIsoTimestamp(instant), timeZone) === day && localHour(instant, timeZone) === hour;
  });
  return toIsoTimestamp(new Date(exact[0] ?? candidates[candidates.length - 1]!));
}

export function shiftLocalDate(day: string, days: number): string {
  return new Date(Date.parse(`${day}T00:00:00.000Z`) + days * DAY_MS).toISOString().slice(0, 10);
}

export function startOfLocalDay(reference: Date, timeZone: string): IsoTimestamp {
  return wallTime(localDate(toIsoTimestamp(reference), timeZone), 0, timeZone);
}

export function localDayBefore(reference: Date, days: number, timeZone: string): IsoTimestamp {
  return wallTime(shiftLocalDate(localDate(toIsoTimestamp(reference), timeZone), -days), 0, timeZone);
}

/** A due date remains current throughout its local calendar day. */
export function isOverdue(
  dueAt: IsoTimestamp | null,
  reference: Date = new Date(),
  timeZone = "UTC",
): boolean {
  return dueAt !== null && localDate(dueAt, timeZone) < localDate(toIsoTimestamp(reference), timeZone);
}

